{
  "name": "Coherent OBIS激光器",
  "name_en": "Coherent OBIS Laser",
  "manufacturer": "Coherent",
  "description": "Coherent OBIS 是一类紧凑型实验室激光光源，可提供稳定的激光输出并支持功率调节与开关控制。此类激光器常用于显微成像、荧光激发、光路搭建与其他需要稳定连续光源的实验场景。",
  "description_en": "The Coherent OBIS is a compact laboratory laser source that provides stable laser output with controllable power and on/off operation. It is commonly used for microscopy, fluorescence excitation, optical alignment, and other experiments requiring a stable continuous light source.",
  "tag_hints": [
    "laser excitation",
    "fluorescence microscopy",
    "output power control",
    "continuous-wave laser",
    "optical alignment",
    "serial-controlled laser"
  ],
  "actions": [
    {
      "action_name": "auto-query",
      "description": "发送串口命令并读取设备返回内容。",
      "description_en": "Send a serial command and read the device response."
    },
    {
      "action_name": "auto-IsOn",
      "description": "查询激光输出是否开启。",
      "description_en": "Check whether the laser output is on."
    },
    {
      "action_name": "auto-TurnOn",
      "description": "开启激光输出。",
      "description_en": "Turn on the laser output."
    },
    {
      "action_name": "auto-TurnOff",
      "description": "关闭激光输出。",
      "description_en": "Turn off the laser output."
    },
    {
      "action_name": "auto-SetPower",
      "description": "设置激光输出功率。",
      "description_en": "Set the laser output power."
    },
    {
      "action_name": "auto-GetPower",
      "description": "读取激光输出功率设定值。",
      "description_en": "Get the laser output power setting."
    },
    {
      "action_name": "auto-Close",
      "description": "关闭与激光器的连接。",
      "description_en": "Close the connection to the laser."
    }
  ]
}

